static std::string str(cJSON*j,const char*k){auto*v=cJSON_GetObjectItem(j,k);return cJSON_IsString(v)?v->valuestring:"";}
static int num(cJSON*j,const char*k,int d){auto*v=cJSON_GetObjectItem(j,k);return cJSON_IsNumber(v)?v->valueint:d;}
static uint32_t le(const unsigned char*b){return uint32_t(b[0])|(uint32_t(b[1])<<8)|(uint32_t(b[2])<<16)|(uint32_t(b[3])<<24);}
bool store_init(){esp_vfs_spiffs_conf_t c{};c.base_path="/data";c.partition_label="works";c.max_files=8;c.format_if_mount_failed=false;return esp_vfs_spiffs_register(&c)==ESP_OK;}
bool validate_work(const char*path,Work&w,std::string&e){
 FILE*f=fopen(path,"rb");if(!f){e="open";return false;}fseek(f,0,SEEK_END);long size=ftell(f);rewind(f);unsigned char h[12];if(fread(h,1,12,f)!=12||memcmp(h,"ND4A",4)){fclose(f);e="header";return false;}uint32_t m=le(h+4),p=le(h+8);if(m<2||m>65536||p>4194304-12-m||size!=12+m+p){fclose(f);e="length";return false;}std::string json(m,' ');bool got=fread(json.data(),1,m,f)==m;fclose(f);auto*j=got?cJSON_ParseWithLength(json.data(),m):nullptr;if(!j){e="json";return false;}
 w={};w.path=path;w.kind=str(j,"template");w.character=str(j,"character");if(w.character.empty())w.character="fox";w.build_id=str(j,"build_id");w.payload_offset=12+m;w.config.seed=(uint32_t)(cJSON_GetObjectItem(j,"seed")?cJSON_GetObjectItem(j,"seed")->valuedouble:1);w.config.speed=num(j,"speed",8);w.config.jump=num(j,"jump",18);w.config.gravity=num(j,"gravity",3);w.config.obstacle_every=num(j,"obstacle_every",400);w.lease_ms=num(j,"lease_ms",60000);
 auto* inputs=cJSON_GetObjectItem(j,"inputs");auto* jumps=cJSON_GetObjectItem(inputs,"jump");bool mapping_ok=true;if(jumps){w.allow_ok=w.allow_wave=false;mapping_ok=cJSON_IsArray(jumps)&&cJSON_GetArraySize(jumps)<=2;for(int i=0;i<cJSON_GetArraySize(jumps);++i){auto*v=cJSON_GetArrayItem(jumps,i);if(!cJSON_IsString(v)){mapping_ok=false;continue;}if(!strcmp(v->valuestring,"ok.short"))w.allow_ok=true;else if(!strcmp(v->valuestring,"gesture.wave"))w.allow_wave=true;else mapping_ok=false;}}
 auto* hud=cJSON_GetObjectItem(j,"gesture_feedback");if(hud){auto* enabled=cJSON_GetObjectItem(hud,"enabled");w.gesture_hud=cJSON_IsTrue(enabled);w.hud_x=num(hud,"x",280);w.hud_y=num(hud,"y",8);auto*style=cJSON_GetObjectItem(hud,"style");w.hud_icon=!cJSON_IsString(style)||strcmp(style->valuestring,"text")!=0;auto*icons=cJSON_GetObjectItem(hud,"icon_set");w.hud_arrows=cJSON_IsString(icons)&&strcmp(icons->valuestring,"arrows")==0;}
 bool ok=(!hud||cJSON_IsObject(hud))&&w.hud_x>=0&&w.hud_x<=304&&w.hud_y>=0&&w.hud_y<=284&&mapping_ok&&num(j,"abi",0)==(w.kind=="js"?3:(w.kind=="reader"||w.kind=="quiz")?2:1)&&!w.build_id.empty()&&w.build_id.size()<=96&&w.lease_ms>=1000&&w.lease_ms<=900000&&w.config.speed>=1&&w.config.speed<=16&&w.config.jump>=6&&w.config.jump<=30&&w.config.gravity>=1&&w.config.gravity<=8&&w.config.obstacle_every>=160&&w.config.obstacle_every<=800;
 if(w.kind=="runner")ok=ok&&(w.allow_ok||w.allow_wave)&&p==0&&(w.character=="fox"||w.character=="penguin");else if(w.kind=="card"){auto*a=cJSON_GetObjectItem(j,"pages");int n=cJSON_GetArraySize(a);ok=ok&&n>0&&n<=8&&p==unsigned(n)*60000;for(int i=0;i<n&&ok;++i){auto*v=cJSON_GetArrayItem(a,i);ok=num(v,"length",0)==60000&&num(v,"offset",-1)==i*60000;w.pages.push_back(i*60000);}}else if(w.kind=="reader"||w.kind=="quiz"){w.compressed=true;auto*a=cJSON_GetObjectItem(j,"pages");int n=cJSON_GetArraySize(a);ok=ok&&cJSON_IsArray(a)&&n>0&&n<=1024;uint32_t offset=0;for(int i=0;i<n&&ok;++i){auto*v=cJSON_GetArrayItem(a,i);int length=num(v,"length",0);ok=length>0&&length<=65536&&num(v,"offset",-1)==int(offset)&&str(v,"encoding")=="deflate4";w.pages.push_back(offset);w.lengths.push_back(length);offset+=length;}ok=ok&&offset==p;if(w.kind=="quiz"){auto*q=cJSON_GetObjectItem(j,"questions");int count=cJSON_GetArraySize(q);ok=ok&&cJSON_IsArray(q)&&count>0&&count<=64&&n==count*3+1;for(int i=0;i<count&&ok;++i){auto*v=cJSON_GetArrayItem(q,i);Question question{num(v,"choices",0),num(v,"answer",-1)};ok=question.choices>=2&&question.choices<=4&&question.answer>=0&&question.answer<question.choices;w.questions.push_back(question);}}}else if(w.kind=="js"){w.app_id=str(j,"app_id");{auto r=str(j,"refresh");w.refresh_mode=r=="clear"?N4_CLEAR:r=="flash"?N4_FLASH:r=="tuned"?N4_TUNED:r=="gray"?N4_GRAY:N4_DOTS;}w.frames=num(j,"frames",0);w.frame_bytes=num(j,"frame_bytes",0);w.frame_deflate=str(j,"frame_codec")=="zlib";{int asset=w.frames?num(j,"asset_bytes",0):0;ok=ok&&w.frames>=0&&w.frames<=128&&(!w.frames||w.frame_bytes==30000||w.frame_bytes==60000)&&asset>=0&&uint32_t(asset)<p&&(!w.frames||asset>0);if(ok)p-=asset;}w.payload_size=p;ok=ok&&p>0&&p<=65536&&w.app_id.size()==8&&strspn(w.app_id.c_str(),"abcdefghijklmnopqrstuvwxyz0123456789")==8;}else ok=false;cJSON_Delete(j);if(!ok)e="abi_or_limits";return ok;
}
bool stage_download(const char*url,size_t length,const char*token,Work&w,std::string&e){
 uint32_t generation=cancellation_generation();if(!artifact_authorized(url)||strncmp(url,"https://",8)||length<14||length>4194304){e="https_or_size";return false;}size_t total=0,used=0;if(esp_spiffs_info("works",&total,&used)!=ESP_OK||total-used<length+32768){e="space";return false;}
 esp_http_client_config_t c{};c.url=url;c.crt_bundle_attach=esp_crt_bundle_attach;c.timeout_ms=10000;c.disable_auto_redirect=true;auto h=esp_http_client_init(&c);if(!h){e="http_init";return false;} std::string auth="Bearer "+std::string(token);esp_http_client_set_header(h,"Authorization",auth.c_str()); // Exact same origin only; redirects disabled.
 bool ok=esp_http_client_open(h,0)==ESP_OK;int64_t declared=ok?esp_http_client_fetch_headers(h):-1;ok=ok&&esp_http_client_get_status_code(h)==200&&(declared<0||size_t(declared)==length);FILE*f=ok?fopen("/data/staging.part","wb"):nullptr;ok=ok&&f;size_t received=0;char buf[4096];while(ok&&received<length&&generation==cancellation_generation()){int n=esp_http_client_read(h,buf,std::min(sizeof(buf),length-received));if(n<=0){ok=false;break;}ok=fwrite(buf,1,n,f)==size_t(n);received+=n;}if(f){fflush(f);fsync(fileno(f));fclose(f);}esp_http_client_close(h);esp_http_client_cleanup(h);if(generation!=cancellation_generation()){remove("/data/staging.part");e="cancelled";return false;}if(!ok||received!=length){remove("/data/staging.part");e="download_incomplete";return false;}return validate_work("/data/staging.part",w,e);
}
bool recover_work(Work&w){nvs_handle_t h;if(nvs_open("note4",NVS_READONLY,&h)!=ESP_OK)return false;char p[40];size_t n=sizeof(p);bool ok=nvs_get_str(h,"active",p,&n)==ESP_OK;nvs_close(h);std::string e;return ok&&validate_work(p,w,e);}
bool activate_work(const Work&w,const std::string&command,std::string&e){Work old;std::string target=recover_work(old)&&old.path=="/data/a.nd4"?"/data/b.nd4":"/data/a.nd4";remove(target.c_str());if(rename(w.path.c_str(),target.c_str())){e="rename";return false;}Work verified;if(!validate_work(target.c_str(),verified,e))return false;nvs_handle_t h;if(nvs_open("note4",NVS_READWRITE,&h)!=ESP_OK){e="nvs_open";return false;}bool ok=nvs_set_str(h,"active",target.c_str())==ESP_OK&&nvs_set_str(h,"active_command",command.c_str())==ESP_OK&&nvs_commit(h)==ESP_OK;nvs_close(h);if(!ok)e="commit";return ok;}
std::string activation_command(){nvs_handle_t h;if(nvs_open("note4",NVS_READONLY,&h)!=ESP_OK)return {};char b[97];size_t n=sizeof(b);bool ok=nvs_get_str(h,"active_command",b,&n)==ESP_OK;nvs_close(h);return ok?b:"";}
bool mark_run(const std::string&command){nvs_handle_t h;if(nvs_open("note4",NVS_READWRITE,&h)!=ESP_OK)return false;bool ok=nvs_set_str(h,"active_command",command.c_str())==ESP_OK&&nvs_commit(h)==ESP_OK;nvs_close(h);return ok;}
void save_reading(const Work&w,int page){if(w.kind!="reader"||page<0||size_t(page)>=w.pages.size())return;nvs_handle_t h;if(nvs_open("note4",NVS_READWRITE,&h)!=ESP_OK)return;nvs_set_str(h,"reader_build",w.build_id.c_str());nvs_set_i32(h,"reader_page",page);nvs_commit(h);nvs_close(h);}
int restore_reading(const Work&w){if(w.kind!="reader")return 0;nvs_handle_t h;if(nvs_open("note4",NVS_READONLY,&h)!=ESP_OK)return 0;char b[97]={};size_t size=sizeof b;int32_t page=0;bool ok=nvs_get_str(h,"reader_build",b,&size)==ESP_OK&&w.build_id==b&&nvs_get_i32(h,"reader_page",&page)==ESP_OK;nvs_close(h);return ok&&page>=0&&size_t(page)<w.pages.size()?page:0;}
bool read_page(const Work&w,int p,uint8_t*out){if(p<0||size_t(p)>=w.pages.size())return false;FILE*f=fopen(w.path.c_str(),"rb");if(!f)return false;fseek(f,w.payload_offset+w.pages[p],SEEK_SET);bool ok=true;if(!w.compressed)ok=fread(out,1,60000,f)==60000;else{auto*packed=(uint8_t*)heap_caps_malloc(w.lengths[p],MALLOC_CAP_SPIRAM);auto*decoder=(tinfl_decompressor*)heap_caps_malloc(sizeof(tinfl_decompressor),MALLOC_CAP_SPIRAM);ok=packed&&decoder&&fread(packed,1,w.lengths[p],f)==w.lengths[p];if(ok){tinfl_init(decoder);size_t input=w.lengths[p],output=60000;ok=tinfl_decompress(decoder,packed,&input,out,out,&output,TINFL_FLAG_PARSE_ZLIB_HEADER|TINFL_FLAG_USING_NON_WRAPPING_OUTPUT_BUF)==TINFL_STATUS_DONE&&output==60000&&input==w.lengths[p];}free(decoder);free(packed);}fclose(f);return ok;}
